export type RefreshAccessTokenResponses = {
    /**
     * Access token; opaque refresh token is set only as an HttpOnly cookie
     */
    200: AccessTokenResponse;
};

export type RefreshAccessTokenResponse = RefreshAccessTokenResponses[keyof RefreshAccessTokenResponses];

export type LogoutData = {
    body?: never;
    headers: {
        'X-XSRF-TOKEN': string;
    };
    path?: never;
    query?: never;
    url: '/api/auth/logout';
};

export type LogoutErrors = {
    /**
     * CSRF validation failed
     */
    403: unknown;
};

export type LogoutResponses = {
    /**
     * Session family revoked and refresh cookie cleared
     */
    204: void;
};

export type LogoutResponse = LogoutResponses[keyof LogoutResponses];

export type CurrentUserData = {
    body?: never;
    path?: never;
    query?: never;
    url: '/api/auth/me';
};

export type CurrentUserErrors = {
    /**
     * Authentication failed
     */
    401: ApiError;
};

export type CurrentUserError = CurrentUserErrors[keyof CurrentUserErrors];

export type CurrentUserResponses = {
    /**
     * Current server-authoritative user
     */
    200: UserResponse;
};

export type CurrentUserResponse = CurrentUserResponses[keyof CurrentUserResponses];
